/// Sorted list of all profile_ids that have a generated requirement entry.
pub fn known_profile_ids() -> Vec<&'static str> {
    PROFILE_REQUIREMENTS.keys().copied().collect()
}

/// Returns the requirements for `profile_id` if it is a known v1 profile.
pub fn requirements_for(profile_id: &str) -> Option<&'static ProfileRequirements> {
    PROFILE_REQUIREMENTS.get(profile_id)
}

/// Returns the exact non-event grant authority rule registered by a profile.
pub fn non_event_grant_authority_rule(
    profile_id: &str,
    grantable_action: &str,
) -> Option<&'static NonEventGrantAuthorityRule> {
    requirements_for(profile_id)?
        .non_event_grant_authority_rules
        .iter()
        .find(|rule| rule.grantable_action == grantable_action)
}

/// Structured failure produced by [`validate_profile_requirements`].
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum ProfileRequirementsError {
    /// `profile_id` is not a v1 profile recognised by the generated table.
    UnknownProfile { profile_id: String },
    /// The profile is known but the caller has not implemented every required
    /// operation / event kind / schema. The vectors are owned, sorted and
    /// deduplicated.
    MissingRequirements {
        profile_id: String,
        missing_operations: Vec<String>,
        missing_event_kinds: Vec<String>,
        missing_schemas: Vec<String>,
    },
}

impl std::fmt::Display for ProfileRequirementsError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::UnknownProfile { profile_id } => {
                write!(f, "unknown conformance profile: {profile_id}")
            }
            Self::MissingRequirements {
                profile_id,
                missing_operations,
                missing_event_kinds,
                missing_schemas,
            } => write!(
                f,
                "profile {profile_id} missing requirements: ops={missing_operations:?} event_kinds={missing_event_kinds:?} schemas={missing_schemas:?}"
            ),
        }
    }
}

impl std::error::Error for ProfileRequirementsError {}

/// Validates that `implemented_*` covers every requirement of `profile_id`.
///
/// Returns `ProfileRequirementsError::UnknownProfile` if `profile_id` is not in
/// the generated table, or `ProfileRequirementsError::MissingRequirements` with
/// sorted-deduplicated diff lists if at least one requirement is unmet.
pub fn validate_profile_requirements(
    profile_id: &str,
    implemented_operations: &[&str],
    implemented_event_kinds: &[&str],
    implemented_schemas: &[&str],
) -> Result<(), ProfileRequirementsError> {
    let Some(req) = PROFILE_REQUIREMENTS.get(profile_id) else {
        return Err(ProfileRequirementsError::UnknownProfile {
            profile_id: profile_id.to_owned(),
        });
    };
    let impl_ops: std::collections::BTreeSet<&str> =
        implemented_operations.iter().copied().collect();
    let impl_kinds: std::collections::BTreeSet<&str> =
        implemented_event_kinds.iter().copied().collect();
    let impl_schemas: std::collections::BTreeSet<&str> =
        implemented_schemas.iter().copied().collect();
    let missing_operations: Vec<String> = req
        .required_operations
        .iter()
        .filter(|op| !impl_ops.contains(*op))
        .map(|s| (*s).to_owned())
        .collect();
    let missing_event_kinds: Vec<String> = req
        .required_event_kinds
        .iter()
        .filter(|kind| !impl_kinds.contains(*kind))
        .map(|s| (*s).to_owned())
        .collect();
    let missing_schemas: Vec<String> = req
        .required_schemas
        .iter()
        .filter(|s| !impl_schemas.contains(*s))
        .map(|s| (*s).to_owned())
        .collect();
    if missing_operations.is_empty() && missing_event_kinds.is_empty() && missing_schemas.is_empty()
    {
        Ok(())
    } else {
        Err(ProfileRequirementsError::MissingRequirements {
            profile_id: profile_id.to_owned(),
            missing_operations,
            missing_event_kinds,
            missing_schemas,
        })
    }
}
